"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[23027],{3331:(a,n,e)=>{e.d(n,{R:()=>s,x:()=>u});var i=e(36672);const r={},t=i.createContext(r);function s(a){const n=i.useContext(t);return i.useMemo((function(){return"function"==typeof a?a(n):{...n,...a}}),[n,a])}function u(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(r):a.components||r:s(a.components),i.createElement(t.Provider,{value:n},a.children)}},34363:(a,n,e)=>{e.r(n),e.d(n,{assets:()=>m,contentTitle:()=>u,default:()=>d,frontMatter:()=>s,metadata:()=>i,toc:()=>k});const i=JSON.parse('{"id":"2023/04/02","title":"02","description":"Perangkat Amazon Echo Menyimpan Kata Sandi WiFi dalam Teks Biasa, Membuatnya Rentan terhadap Serangan Akses Fisik","source":"@site/i18n/id/docusaurus-plugin-content-docs/current/2023/04/02.md","sourceDirName":"2023/04","slug":"/2023/04/02","permalink":"/id/2023/04/02","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/id/docusaurus-plugin-content-docs//current/2023/04/02.md","tags":[],"version":"current","frontMatter":{"localized_date":"2 April 2023","top_news":"Perangkat Amazon Echo Menyimpan Kata Sandi WiFi dalam Teks Biasa, Membuatnya Rentan terhadap Serangan Akses Fisik"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-03","permalink":"/id/2023/04/03"},"next":{"title":"01","permalink":"/id/2023/04/01"}}');var r=e(23420),t=e(3331);const s={localized_date:"2 April 2023",top_news:"Perangkat Amazon Echo Menyimpan Kata Sandi WiFi dalam Teks Biasa, Membuatnya Rentan terhadap Serangan Akses Fisik"},u=void 0,m={},k=[{value:"Perangkat Amazon Echo Menyimpan Kata Sandi WiFi dalam Teks Biasa, Membuatnya Rentan terhadap Serangan Akses Fisik",id:"perangkat-amazon-echo-menyimpan-kata-sandi-wifi-dalam-teks-biasa-membuatnya-rentan-terhadap-serangan-akses-fisik",level:2},{value:"Google Drive memberlakukan batas file, berpotensi memotong pelanggan yang membayar",id:"google-drive-memberlakukan-batas-file-berpotensi-memotong-pelanggan-yang-membayar",level:2},{value:"Panduan untuk Desain Jam Logis untuk Pengurutan Kejadian yang Andal dalam Sistem Terdistribusi",id:"panduan-untuk-desain-jam-logis-untuk-pengurutan-kejadian-yang-andal-dalam-sistem-terdistribusi",level:2},{value:"Jalur HexaTrek sepanjang 3034 km di Prancis Dibuka untuk Penjelajahan",id:"jalur-hexatrek-sepanjang-3034-km-di-prancis-dibuka-untuk-penjelajahan",level:2},{value:"Pengembang Raph Levien berpindah dari Rust ke C++",id:"pengembang-raph-levien-berpindah-dari-rust-ke-c",level:2},{value:"Coursemate: Menghubungkan Pembelajar Mandiri di Seluruh Dunia untuk Pembelajaran Online Kolaboratif",id:"coursemate-menghubungkan-pembelajar-mandiri-di-seluruh-dunia-untuk-pembelajaran-online-kolaboratif",level:2},{value:"Tanaman mengeluarkan suara saat stres, membuka pintu baru untuk memahami",id:"tanaman-mengeluarkan-suara-saat-stres-membuka-pintu-baru-untuk-memahami",level:2},{value:"Simulasi Sistem BBS Bawah Tanah dari tahun 1987: Obrolan, Permainan, &amp; Email",id:"simulasi-sistem-bbs-bawah-tanah-dari-tahun-1987-obrolan-permainan--email",level:2},{value:"Google menunda mematikan Manifes V2 untuk ekstensi Chrome",id:"google-menunda-mematikan-manifes-v2-untuk-ekstensi-chrome",level:2},{value:"Wine 8.5: Peningkatan vkd3d, Tema WinRT, &amp; Perbaikan Bug",id:"wine-85-peningkatan-vkd3d-tema-winrt--perbaikan-bug",level:2},{value:"Melanjutkan Proses Perekrutan Pertama: Eksploitatif &amp; Tidak Efektif",id:"melanjutkan-proses-perekrutan-pertama-eksploitatif--tidak-efektif",level:2},{value:"Mantan Staf SpaceX Dirikan Puluhan Startup Antariksa, Kumpulkan Dana $3,6 Miliar",id:"mantan-staf-spacex-dirikan-puluhan-startup-antariksa-kumpulkan-dana-36-miliar",level:2},{value:"Pesawat luar angkasa SpaceX bergerak ke lokasi peluncuran, kemungkinan lepas landas pada 10 April",id:"pesawat-luar-angkasa-spacex-bergerak-ke-lokasi-peluncuran-kemungkinan-lepas-landas-pada-10-april",level:2},{value:"&#39;ccurl.sh&#39; memungkinkan cURL untuk memanfaatkan cookie Chrome dengan cara yang ringkas",id:"ccurlsh-memungkinkan-curl-untuk-memanfaatkan-cookie-chrome-dengan-cara-yang-ringkas",level:2},{value:"Kursus MIT tentang RNN &amp; Transformers untuk Deep Learning",id:"kursus-mit-tentang-rnn--transformers-untuk-deep-learning",level:2}];function l(a){const n={a:"a",h2:"h2",p:"p",strong:"strong",...(0,t.R)(),...a.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.h2,{id:"perangkat-amazon-echo-menyimpan-kata-sandi-wifi-dalam-teks-biasa-membuatnya-rentan-terhadap-serangan-akses-fisik",children:"Perangkat Amazon Echo Menyimpan Kata Sandi WiFi dalam Teks Biasa, Membuatnya Rentan terhadap Serangan Akses Fisik"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Alexa, apa kata sandi wifi saya?"}),"\nPerangkat Amazon Echo menyimpan kata sandi WiFi dalam bentuk teks biasa, sehingga memungkinkan penyerang yang memiliki akses fisik untuk mengekstrak kata sandi jaringan dengan relatif mudah. Hal ini menimbulkan risiko keamanan yang besar bagi hotel atau bisnis yang menggunakan perangkat pada jaringan nirkabel internal atau pribadi mereka, memberikan penyerang akses ke peralatan lain di jaringan, yang berpotensi melanggar Undang-Undang Perlindungan Data. Meng-hash kata sandi adalah standar industri, dan untuk perusahaan yang telah menjual perangkat keras mereka kepada jutaan orang, sangat tidak dapat diterima untuk tidak mengenkripsi data ini. Perangkat ini tidak mengenkripsi kunci API untuk Spotify zeroconf dan API eSDK. Keamanan fisik sangat penting saat merancang perangkat keras tertanam, dan Amazon perlu mengatasi masalah ini untuk mencegah pelanggaran keamanan di masa depan.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35399590",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://dragon863.github.io/blog/alexa.html",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"google-drive-memberlakukan-batas-file-berpotensi-memotong-pelanggan-yang-membayar",children:"Google Drive memberlakukan batas file, berpotensi memotong pelanggan yang membayar"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Google Drive secara mengejutkan memberlakukan batas file, mengunci beberapa pengguna."}),".\nGoogle Drive telah memberlakukan batas file tanpa peringatan, sehingga berpotensi membuat pelanggan berbayar tidak dapat mengunggah file baru; pengguna Reddit telah mengeluhkan masalah ini selama dua bulan terakhir. Peluncuran batas file secara tiba-tiba tidak tercantum pada halaman paket Google One atau Google Workspace atau disebutkan dalam dokumen dukungan. Hal ini juga mencegah pengguna untuk memanfaatkan penyimpanan yang mereka beli, karena batas tersebut mencegah mereka untuk menggunakan ruang tersebut. Batas 5 juta file Google Drive dianggap tidak dapat diterima atau masuk akal oleh banyak pengguna karena tidak didokumentasikan di mana pun, dan biaya penggunaan paket penyimpanan Google Workspace dianggap terlalu tinggi. Google berargumen bahwa batas tersebut merupakan perlindungan untuk mencegah penyalahgunaan sistem yang dapat mempengaruhi stabilitas dan keamanannya, namun komunikasi dengan pelanggan seperti itu dianggap buruk.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35397071",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://arstechnica.com/gadgets/2023/03/google-drive-does-a-surprise-rollout-of-file-limits-locking-out-some-users/",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"panduan-untuk-desain-jam-logis-untuk-pengurutan-kejadian-yang-andal-dalam-sistem-terdistribusi",children:"Panduan untuk Desain Jam Logis untuk Pengurutan Kejadian yang Andal dalam Sistem Terdistribusi"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Jam dan Kausalitas - Pemesanan Peristiwa dalam Sistem Terdistribusi (2022)."}),".\nJam logis sangat penting dalam mengurutkan kejadian dalam sistem terdistribusi, dengan Lamport dan jam vektor menjadi desain yang populer. Jam Lamport memberikan jumlah yang meningkat dalam sebuah node, sementara jam vektor melacak ID node dan ID peristiwa masing-masing untuk perbandingan peristiwa bersamaan. Dotted Vector Clock dan Vector Timestamps mengoptimalkan pemeriksaan stempel waktu dan memungkinkan pengurutan peristiwa di seluruh node. Vektor versi melacak versi data dalam node penyimpanan multi-leader. Lamport Causal Clock menangkap kausalitas tetapi membutuhkan lebih banyak ruang dan kompleksitas waktu. Total Order membutuhkan pemesanan berurutan berdasarkan hubungan temporal dan kausal. Jam logis sangat penting dalam aplikasi pengeditan kolaboratif. Azure Time Sync menggunakan PTP, sedangkan AWS dan Google Cloud menggunakan NTP. Artikel ini mencatat keterbatasan dalam mencoba menganggap waktu sebagai sesuatu yang mutlak dan menyoroti pentingnya urutan peristiwa dalam transaksi perbankan.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35399603",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://www.exhypothesi.com/clocks-and-causality/",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"jalur-hexatrek-sepanjang-3034-km-di-prancis-dibuka-untuk-penjelajahan",children:"Jalur HexaTrek sepanjang 3034 km di Prancis Dibuka untuk Penjelajahan"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Hexatrek: Pendakian jarak jauh di Prancis."}),"\nJalur HexaTrek sepanjang 3034 km di Prancis kini dibuka untuk pendakian lintas alam, menghubungkan 14 taman nasional dan melintasi jalur Via Transilvania di Rumania.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35397051",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://en.hexatrek.com",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"pengembang-raph-levien-berpindah-dari-rust-ke-c",children:"Pengembang Raph Levien berpindah dari Rust ke C++"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Pindah dari Rust ke C++."}),".\nPengembang Raph Levien mengumumkan keputusannya untuk berpindah dari Rust ke C++ karena keterbatasan yang dimiliki oleh bahasa pemrograman sebelumnya, seperti kurangnya pilihan build system dan lambatnya perkembangan inovasi, terlepas dari jaminan keamanannya. Levien percaya bahwa ia dapat menghindari masalah keamanan dan bahwa bug keamanan memori tidak secara signifikan lebih berbahaya daripada bug lainnya, dan bahwa C++ berkembang dengan cepat untuk menjadi lebih aman. Levien menekankan pentingnya komunitas, menyuarakan keprihatinan tentang kebijakan diskriminasi dan para pendukung Rust yang tampaknya sombong. Namun, artikel ini bersifat satir, dan beberapa pembaca menyatakan ketertarikannya pada C++ daripada Rust.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35400047",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://raphlinus.github.io/rust/2023/04/01/rust-to-cpp.html",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"coursemate-menghubungkan-pembelajar-mandiri-di-seluruh-dunia-untuk-pembelajaran-online-kolaboratif",children:"Coursemate: Menghubungkan Pembelajar Mandiri di Seluruh Dunia untuk Pembelajaran Online Kolaboratif"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Tampilkan Coursemate - terhubung dengan pembelajar mandiri lainnya."}),"\nCoursemate adalah sebuah platform bagi para pembelajar mandiri untuk terhubung dan berkolaborasi dalam kursus online dengan rekan-rekan di negara mereka atau di seluruh dunia. Platform ini dapat berintegrasi dengan kursus online favorit pengguna dan membutuhkan waktu kurang dari satu menit untuk menyiapkannya. Beberapa pengguna menyarankan agar Coursemate dapat mengambil manfaat dari tujuan pembelajaran yang lebih spesifik di luar fokus saat ini pada topik frontend dan backend. Selain itu, pengguna ingin melihat lebih banyak contoh komunitas dan peluang bimbingan. Beberapa pengguna juga menyarankan untuk memperluas penyaringan berdasarkan usia dan negara untuk memungkinkan penyaringan berdasarkan minat. Meskipun ada beberapa kritik, situs web ini dijalankan dengan baik dan lugas. Beberapa pengguna mengungkapkan keinginan mereka untuk memiliki platform yang dapat menghubungkan mereka dengan para ahli yang dapat membantu menjelaskan konten kursus tertentu.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35398480",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://www.coursem8.com/",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"tanaman-mengeluarkan-suara-saat-stres-membuka-pintu-baru-untuk-memahami",children:"Tanaman mengeluarkan suara saat stres, membuka pintu baru untuk memahami"}),"\n",(0,r.jsxs)(n.p,{children:["**Suara yang dipancarkan oleh tanaman yang sedang stres dapat menyebar ke udara dan bersifat informatif.\nTanaman dapat mengeluarkan suara yang informatif di udara saat mengalami stres, membuka jalan untuk memahami interaksi mereka dengan lingkungan. Bidang baru bioakustik tanaman ini memperkenalkan potensi komunikasi akustik tanaman, yang dapat dideteksi oleh model pembelajaran mesin dan dapat berdampak pada pertanian di luar isyarat tradisional.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35396156",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://www.cell.com/cell/fulltext/S0092-8674(23)00262-3",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"simulasi-sistem-bbs-bawah-tanah-dari-tahun-1987-obrolan-permainan--email",children:"Simulasi Sistem BBS Bawah Tanah dari tahun 1987: Obrolan, Permainan, & Email"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"ChatGPT mensimulasikan Sistem BBS tahun 1987."}),".\nArtikel ini membahas simulasi sistem BBS dari tahun 1987, termasuk obrolan, permainan, dan email. Pengguna dapat membuat akun, membaca berita dan dokumentasi, melihat file teks, dan berkomunikasi dengan pengguna lain. Castle Quest, sebuah permainan berbasis teks, dapat dimainkan pada sistem. ShareGPT memungkinkan berbagi cuplikan kode dalam percakapan. Keakuratan historis dari keluaran ChatGPT masih dipertanyakan, tetapi menarik. Seorang pengguna menyarankan untuk mensimulasikan BBS tahun 1987 dengan fitur tambahan. Artikel ini memberikan pandangan nostalgia pada teknologi masa lalu.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35396165",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://sharegpt.com/c/ICZsSl7",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"google-menunda-mematikan-manifes-v2-untuk-ekstensi-chrome",children:"Google menunda mematikan Manifes V2 untuk ekstensi Chrome"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Menunda perubahan penghapusan Manifest V2."}),".\nGoogle telah menunda percobaan pada bulan Januari untuk mematikan Manifest V2 di saluran pra-rilis Chrome dan perubahan pada lencana fitur di Chrome Webstore, dan akan mengevaluasi semua pencapaian hilir. Para pengembang akan diberikan waktu yang cukup untuk memperbarui dan menguji ekstensi mereka setelah peluncuran kemampuan baru ini sebelum mematikan Manifest V2. Komitmen Google untuk meluncurkan Manifest V3 diharapkan dapat meningkatkan keamanan, privasi, dan kinerja bagi para penggunanya. Terdapat umpan balik dari komunitas pengembang mengenai kesulitan dalam menggunakan Manifest V3, beberapa di antaranya telah diatasi, namun masih ada perbaikan yang harus dilakukan, dan Google tetap berkomitmen untuk melakukan transisi.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35402698",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://groups.google.com/a/chromium.org/g/chromium-extensions/c/zQ77HkGmK9E/m/HjaaCIG-BQAJ",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"wine-85-peningkatan-vkd3d-tema-winrt--perbaikan-bug",children:"Wine 8.5: Peningkatan vkd3d, Tema WinRT, & Perbaikan Bug"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Wine 8.5."}),"\nRilis Wine 8.5 hadir dengan vkd3d yang lebih baik, WinRT Theme, dan perbaikan bug, termasuk pelaporan kesalahan yang lebih baik di kompiler IDL, dukungan untuk UIA_IsOffscreenPropertyId untuk penyedia MSAA, dan inisialisasi penuh konteks FPU i386 pada ARM64. Paket biner tersedia untuk berbagai distribusi, dan sumber tersedia langsung dari repositori git. Perbaikan bug termasuk mscoree, imm32, dan pengikatan LDAP.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35398643",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://www.winehq.org/announce/8.5",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"melanjutkan-proses-perekrutan-pertama-eksploitatif--tidak-efektif",children:"Melanjutkan Proses Perekrutan Pertama: Eksploitatif & Tidak Efektif"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Dia yang mengirimkan resume sudah kalah."}),".\nProses perekrutan tradisional yang mengutamakan resume adalah proses yang eksploitatif dan pada akhirnya tidak efektif, dengan pemberi kerja yang menggunakannya terutama untuk menghemat waktu dan memangkas biaya atas biaya pelamar. Resume dapat diabaikan, dan rekomendasi pribadi serta jaringan merupakan metode yang lebih efektif untuk mendapatkan pekerjaan, melewati proses yang cacat dan tidak adil. Perekrutan akademis sangat menurunkan semangat dan nepotisme dapat menimbulkan masalah etika. Para pencari kerja harus melakukan apa yang mereka bisa untuk menghindari sistem ini, namun tetap saja membuat resume dengan serius. Postingan ini menawarkan alat bantu bagi para pencari kerja untuk tampil menonjol, termasuk menulis surat lamaran atau menggunakan alat bantu AI untuk menulisnya dalam dua menit.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35397271",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://www.residentcontrarian.com/p/he-who-submits-a-resume-has-already",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"mantan-staf-spacex-dirikan-puluhan-startup-antariksa-kumpulkan-dana-36-miliar",children:"Mantan Staf SpaceX Dirikan Puluhan Startup Antariksa, Kumpulkan Dana $3,6 Miliar"}),"\n",(0,r.jsxs)(n.p,{children:["**Para alumni SpaceX mulai merambah dan membentuk ekonomi startup.\nMantan karyawan SpaceX mendirikan puluhan perusahaan rintisan antariksa, mengumpulkan dana sebesar $3,6 miliar untuk mendorong inovasi dalam navigasi Orbit Rendah Bumi dan layanan pengiriman muatan. Para pendiri mendapat manfaat dari komunitas dan toleransi risiko tinggi yang dibangun di SpaceX, dengan layanan peluncuran yang juga membantu prototipe teknologi, mesin, dan pengiriman satelit navigasi. Industri perangkat lunak sebagai layanan tumbuh, melayani ekosistem startup luar angkasa. Langkah NASA dan Boeing dapat memperoleh manfaat dari menumbuhkan budaya startup karena kode warisan dan cruft menghambat para petahana. Peluang dalam eksplorasi ruang angkasa memberikan likuiditas di pasar, dan investor menerima jutaan dolar untuk percobaan yang berisiko. Beberapa komentar menyatakan bahwa artikel ini terasa seperti siaran pers.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35404823",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://interactive.satellitetoday.com/via/april-2023/how-spacex-alums-are-branching-out-and-shaping-the-startup-economy/",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"pesawat-luar-angkasa-spacex-bergerak-ke-lokasi-peluncuran-kemungkinan-lepas-landas-pada-10-april",children:"Pesawat luar angkasa SpaceX bergerak ke lokasi peluncuran, kemungkinan lepas landas pada 10 April"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"SpaceX memindahkan pesawat luar angkasa ke lokasi peluncuran, dan peluncurannya mungkin akan dilakukan dalam beberapa hari lagi."}),"\nSpaceX telah memindahkan Starship mereka ke lokasi peluncuran di Texas Selatan, yang dapat siap untuk lepas landas secepatnya pada tanggal 10 April, sambil menunggu perizinan dari FAA. Roket raksasa Super Heavy dimaksudkan untuk melayani NASA sebagai pendarat di bulan untuk misi Bulan Artemis. SpaceX telah menginvestasikan lebih dari $1 miliar di menara peluncuran dan penangkapnya untuk mendukung Starship dan Super Heavy, yang telah dikembangkan dengan lebih hati-hati di fasilitasnya di Texas Selatan. Jika berhasil, hal ini dapat membuat orbit rendah bumi menjadi lebih mudah diakses oleh para profesional.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35405030",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://arstechnica.com/science/2023/04/spacex-moves-starship-to-launch-site-and-liftoff-could-be-just-days-away/",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"ccurlsh-memungkinkan-curl-untuk-memanfaatkan-cookie-chrome-dengan-cara-yang-ringkas",children:"'ccurl.sh' memungkinkan cURL untuk memanfaatkan cookie Chrome dengan cara yang ringkas"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"Tampilkan Gunakan cookie dari Chrome (CDP) di cURL tanpa menyalin dan menempel."}),'.\n\'ccurl.sh\' adalah skrip bash yang memungkinkan cURL menggunakan cookie Chrome tanpa memerlukan alat GUI seperti Postman, menggunakan protokol Chrome DevTools untuk membuang cookie dari tab tertentu pada instans Chrome lokal ke dalam header perintah cURL, dan menghindari kebocoran cookie ke dalam berkas riwayat shell; skrip membutuhkan bash, websocat, dan jq untuk menjalankannya, dan sebuah tab dengan cookie yang akan digunakan untuk dibuka di Chrome, yang harus dijalankan dengan "google-chrome-stable --remote-debugging-port=9222", dan dapat diinstal dengan menyalin skrip ke "/usr/bin/ccurl" dan membuatnya dapat dieksekusi.\n',(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35399218",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://github.com/fipso/ccurl.sh",children:"Artikel"}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"kursus-mit-tentang-rnn--transformers-untuk-deep-learning",children:"Kursus MIT tentang RNN & Transformers untuk Deep Learning"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"MIT 6.S191: Jaringan Saraf Tiruan, Transformator, dan Perhatian."}),".\nMata kuliah 6.S191 dari MIT mencakup jaringan saraf tiruan (RNN), transformer, dan perhatian untuk pembelajaran mendalam, seperti yang ditampilkan di YouTube. Komentar-komentar pada video tersebut berkisar dari mempertanyakan konvensi penamaan parameter hingga meminta rekomendasi tempat untuk mempelajari jaringan syaraf tiruan dan dasar-dasar deep learning. Penggunaan TensorFlow dalam kursus ini dan pengunggahan video ke saluran YouTube masing-masing anggota staf juga dibahas.\n",(0,r.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35405338",children:"Discussion Service"}),", ",(0,r.jsx)(n.a,{href:"https://www.youtube.com/watch?v=ySEx_Bqxvvo",children:"Artikel"}),"."]})]})}function d(a={}){const{wrapper:n}={...(0,t.R)(),...a.components};return n?(0,r.jsx)(n,{...a,children:(0,r.jsx)(l,{...a})}):l(a)}}}]);